    "summary": "호랑이가 많아, 지난해 겨울부터 금년 봄에 이르기까지 호랑이에게 죽은 사람이 기백 명입니다. 연해 군현(沿海郡縣)이 더욱 많아 사람들이 길을 잘 갈 수 없사온데, 하물며 밭을 갈고 김을 맬 수 있겠습니까? 하니, 임금이 즉시 그 도(道)의 관찰사(觀察使)·절제사(節制使)에게 명하였다. \"이제부터 호랑이에게 상하는 자가 있다면 비록 한 사람이라도 죄를 주겠다.\"",
