    "yasaStory": "1413년(태종 13년) 2월 7일 실록에 실제로 기록된 이야기입니다.\n\n당시 조정과 백성들 사이에서 일어난 이 사건은 《태종실록 25권》에 다음과 같이 생생히 남아 있습니다.\n\n\"두려워서 몸을 움츠리고 있었는데, 김씨가 홀로 나가니 호랑이가 남편을 잡아가므로, 김씨는 남편의 목 궁(木弓)을 들고 소리치며 뒤쫓아 따라갔습니다. 왼손으로 남편을 붙잡고 오른손으로 호랑이를 때리며 거의 60보(步)나 가니, 호랑이가 남편을 버리고 우뚝 섰습니다. 김씨가 말하기를, ‘너는 내 남편을 잡고 나까지 잡아 가려 하느냐?’ 하자, 호랑이는 곧 가버리고 남편은 이미 죽었습니다. ...\"\n\n(※ 원문 전체 및 한문 원전은 국사편찬위원회 조선왕조실록 링크에서 확인하실 수 있습니다.)",
