    "yasaStory": "1417년(태종 17년) 12월 4일 실록에 실제로 기록된 이야기입니다.\n\n당시 조정과 백성들 사이에서 일어난 이 사건은 《태종실록 34권》에 다음과 같이 생생히 남아 있습니다.\n\n\"호랑이를 잡는 위급한 일이 있으면, 소재지의 관사(官司)에 곧 군사를 조발하여 책응하고, 본도 감사에게 급히 보고하여 사유를 갖추어 본조(本曹)에 이문(移文)하면, 본조에서 사실을 조사하여 계달(啓達)하게 하는 것으로써 항식(恒式)을 삼으소서.\" 둔취(屯聚) 여러사람이 한곳에 모여 있음. 임금이 그대로 따랐다. 이보다 앞서 목장에 호랑이가 있어 그 고을의 수령이 군사를 조발하여 구축하였는데...\"\n\n(※ 원문 전체 및 한문 원전은 국사편찬위원회 조선왕조실록 링크에서 확인하실 수 있습니다.)",
