    "yasaStory": "1443년(세종 25년) 11월 6일 실록에 실제로 기록된 이야기입니다.\n\n당시 조정과 백성들 사이에서 일어난 이 사건은 《세종실록 102권》에 다음과 같이 생생히 남아 있습니다.\n\n\"호랑이에게 잡혀 갔사온데, 검진이 호랑이를 쫓아 어미를 빼앗아 밤새도록 구호하였으나, 이튿날 어미가 죽으매 검진이 시묘(侍墓)하여 예를 다하였으니, 청하건대, 정문(旌門)하고 복호(復戶)하게 하소서.\" 하니, 그대로 따랐다.\"\n\n(※ 원문 전체 및 한문 원전은 국사편찬위원회 조선왕조실록 링크에서 확인하실 수 있습니다.)",
