    "yasaStory": "1417년(태종 17년) 2월 22일 실록에 실제로 기록된 이야기입니다.\n\n당시 조정과 백성들 사이에서 일어난 이 사건은 《태종실록 33권》에 다음과 같이 생생히 남아 있습니다.\n\n\"목 대왕(穆祖仁文聖穆大王)·익조 강혜 성익 대왕(翼祖康惠聖翼大王)·도조 공의 성도 대왕(度祖恭毅聖度大王)·환조 연무 성환 대왕(桓祖淵武聖桓大王)·태조 강헌 지인 계운 성문 신무 대왕(太祖康獻至仁啓運聖文神武大王)의 영전에 밝게 고합니다. 엎드려 공손히 생각하건대, 조종(祖宗)께서 적공누인(積功累仁)하여, 우리 태조 때에 성한 덕과 높은 공으로 능히 천심(天心)을 누림에 집안을 화하여 나...\"\n\n(※ 원문 전체 및 한문 원전은 국사편찬위원회 조선왕조실록 링크에서 확인하실 수 있습니다.)",
