    "summary": "없이 어질고 덕이 있는 사람을 생각하여 차서(次序)를 유성(維城)에 전하여, 신명(神明)의 계통을 계속시켜 고비(考妣)의 광화(光華)를 삼으려고 살펴보고 간택(簡擇)하기 위하여 지금까지 끌어 왔다. 주 왕(周王)이 종실(宗室)의 장(長)으로서 여러번 표(表)를 올려 태자(太子)를 세우고 여러 왕(王)을 봉(封)하여 세울 것을 청하였고, 종실(宗室)과 군신(群臣)·백성(百姓)들이 말을 합...",
    "officialRecord": "없이 어질고 덕이 있는 사람을 생각하여 차서(次序)를 유성(維城)에 전하여, 신명(神明)의 계통을 계속시켜 고비(考妣)의 광화(光華)를 삼으려고 살펴보고 간택(簡擇)하기 위하여 지금까지 끌어 왔다. 주 왕(周王)이 종실(宗室)의 장(長)으로서 여러번 표(表)를 올려 태자(太子)를 세우고 여러 왕(王)을 봉(封)하여 세울 것을 청하였고, 종실(宗室)과 군신(群臣)·백성(百姓)들이 말을 합...",
    "yasaStory": "1404년(태종 4년) 6월 10일 실록에 실제로 기록된 이야기입니다.\n\n당시 조정과 백성들 사이에서 일어난 이 사건은 《태종실록 7권》에 다음과 같이 생생히 남아 있습니다.\n\n\"없이 어질고 덕이 있는 사람을 생각하여 차서(次序)를 유성(維城)에 전하여, 신명(神明)의 계통을 계속시켜 고비(考妣)의 광화(光華)를 삼으려고 살펴보고 간택(簡擇)하기 위하여 지금까지 끌어 왔다. 주 왕(周王)이 종실(宗室)의 장(長)으로서 여러번 표(表)를 올려 태자(太子)를 세우고 여러 왕(王)을 봉(封)하여 세울 것을 청하였고, 종실(宗室)과 군신(群臣)·백성(百姓)들이 말을 합...\"\n\n(※ 원문 전체 및 한문 원전은 국사편찬위원회 조선왕조실록 링크에서 확인하실 수 있습니다.)",
