    "summary": "일식(日食)이나 월식(月食)이 있을 때 임금이 각사(各司)의 당상관(堂上官)과 낭관(郞官)을 거느리고 해나 달이 복원(復圓)할 때까지 기도 드리던 일. \"처음에 변정 도감(辨正都監)을 설치하였을 때 간혹 비난하는 자가 있었는데, 이제 이미 판결(判決)을 끝냈으나, 원망이 그치지 않고 신정(申呈)하는 자가 많다. 이제 기후(氣候)가 순조롭지 못하니, 어찌 원기(怨氣)의 소치로 그렇지 않겠느냐...",
    "officialRecord": "일식(日食)이나 월식(月食)이 있을 때 임금이 각사(各司)의 당상관(堂上官)과 낭관(郞官)을 거느리고 해나 달이 복원(復圓)할 때까지 기도 드리던 일. \"처음에 변정 도감(辨正都監)을 설치하였을 때 간혹 비난하는 자가 있었는데, 이제 이미 판결(判決)을 끝냈으나, 원망이 그치지 않고 신정(申呈)하는 자가 많다. 이제 기후(氣候)가 순조롭지 못하니, 어찌 원기(怨氣)의 소치로 그렇지 않겠느냐...",
    "yasaStory": "1414년(태종 14년) 11월 16일 실록에 실제로 기록된 이야기입니다.\n\n당시 조정과 백성들 사이에서 일어난 이 사건은 《태종실록 28권》에 다음과 같이 생생히 남아 있습니다.\n\n\"일식(日食)이나 월식(月食)이 있을 때 임금이 각사(各司)의 당상관(堂上官)과 낭관(郞官)을 거느리고 해나 달이 복원(復圓)할 때까지 기도 드리던 일. \"처음에 변정 도감(辨正都監)을 설치하였을 때 간혹 비난하는 자가 있었는데, 이제 이미 판결(判決)을 끝냈으나, 원망이 그치지 않고 신정(申呈)하는 자가 많다. 이제 기후(氣候)가 순조롭지 못하니, 어찌 원기(怨氣)의 소치로 그렇지 않겠느냐...\"\n\n(※ 원문 전체 및 한문 원전은 국사편찬위원회 조선왕조실록 링크에서 확인하실 수 있습니다.)",
