    "yasaStory": "1431년(세종 13년) 12월 19일 실록에 실제로 기록된 이야기입니다.\n\n당시 조정과 백성들 사이에서 일어난 이 사건은 《세종실록 54권》에 다음과 같이 생생히 남아 있습니다.\n\n\"일식의 변고가 있으면 향궐 하례(向闕賀禮)를 정지했는데, 지금부터 이러한 재변을 만나면 악부는 진설만 하고 잡히지 않으며 다만 하례만 행하는 것이 어떠한가. 그것을 예조로 하여금 헤아려 의논하여 아뢰도록 하라.\" 하였다.\"\n\n(※ 원문 전체 및 한문 원전은 국사편찬위원회 조선왕조실록 링크에서 확인하실 수 있습니다.)",
