    "summary": "합니다. 지금은 다행히 백일(白日)이 중천(中天)하여 도깨비가 두려워하나, 청조( 淸朝)의 수치는 대단히 심합니다. 내치가 이렇게 미진한 것을 어떻게 이웃 적에게 듣게 하겠습니까. 반드시 교화를 밝혀 인심을 맑히고, 기강을 세워 군정(軍政)을 닦으며, 미천하여 버려진 인재를 널리 찾고, 거꾸로 매달려 고할 데 없는 백성의 고통을 잘 돌보아, 공도(公道)가 행해지고 사유(四維)가 펴지게 ...",
    "officialRecord": "합니다. 지금은 다행히 백일(白日)이 중천(中天)하여 도깨비가 두려워하나, 청조( 淸朝)의 수치는 대단히 심합니다. 내치가 이렇게 미진한 것을 어떻게 이웃 적에게 듣게 하겠습니까. 반드시 교화를 밝혀 인심을 맑히고, 기강을 세워 군정(軍政)을 닦으며, 미천하여 버려진 인재를 널리 찾고, 거꾸로 매달려 고할 데 없는 백성의 고통을 잘 돌보아, 공도(公道)가 행해지고 사유(四維)가 펴지게 ...",
    "yasaStory": "1606년(선조 39년) 10월 25일 실록에 실제로 기록된 이야기입니다.\n\n당시 조정과 백성들 사이에서 일어난 이 사건은 《선조실록 204권》에 다음과 같이 생생히 남아 있습니다.\n\n\"합니다. 지금은 다행히 백일(白日)이 중천(中天)하여 도깨비가 두려워하나, 청조( 淸朝)의 수치는 대단히 심합니다. 내치가 이렇게 미진한 것을 어떻게 이웃 적에게 듣게 하겠습니까. 반드시 교화를 밝혀 인심을 맑히고, 기강을 세워 군정(軍政)을 닦으며, 미천하여 버려진 인재를 널리 찾고, 거꾸로 매달려 고할 데 없는 백성의 고통을 잘 돌보아, 공도(公道)가 행해지고 사유(四維)가 펴지게 ...\"\n\n(※ 원문 전체 및 한문 원전은 국사편찬위원회 조선왕조실록 링크에서 확인하실 수 있습니다.)",
