    "yasaStory": "1414년(태종 14년) 2월 13일 실록에 실제로 기록된 이야기입니다.\n\n당시 조정과 백성들 사이에서 일어난 이 사건은 《태종실록 27권》에 다음과 같이 생생히 남아 있습니다.\n\n\"역모(逆謀)에 참여하였다 하더라도 장인 조곤이 먼저 고(告)하였으므로 처자 형제가 연좌(連坐)를 면하였습니다. 이제부터 부형(父兄)이 범죄한 자라도 연좌의 율(律)을 범한 경우를 제외하고는 자제(子弟)가 부시(赴試)하고 서용(敍用)하는 것을 허락하소서.\" 임금이 그대로 따랐다.\"\n\n(※ 원문 전체 및 한문 원전은 국사편찬위원회 조선왕조실록 링크에서 확인하실 수 있습니다.)",
