    "yasaStory": "1400년(정종 2년) 6월 2일 실록에 실제로 기록된 이야기입니다.\n\n당시 조정과 백성들 사이에서 일어난 이 사건은 《정종실록 4권》에 다음과 같이 생생히 남아 있습니다.\n\n\"금주령(禁酒令)을 내려 경비를 절약하게 하소서.\" \"방금 사방의 큰 폐단은 오로지 노비(奴婢) 한 가지 일입니다. 태상왕께서 깊이 그 폐단을 아시고, 노비 변정 도감(奴婢辨定都監)을 설치하여 모두 공평하게 판결해서 쟁송(爭訟)이 없어지게 하였습니다. 지금 전하께서 사헌부로 하여금 변정 도감의 오결(誤決)한 소지(所志)를 받아서 형조와 도관(都官)에게 나누어 붙여 판결하게 하였습니다. 신 등...\"\n\n(※ 원문 전체 및 한문 원전은 국사편찬위원회 조선왕조실록 링크에서 확인하실 수 있습니다.)",
