    "yasaStory": "1402년(태종 2년) 4월 24일 실록에 실제로 기록된 이야기입니다.\n\n당시 조정과 백성들 사이에서 일어난 이 사건은 《태종실록 3권》에 다음과 같이 생생히 남아 있습니다.\n\n\"금주령(禁酒令)을 여러 도(道)에 내리셨사온데, 경중(京中)은 그렇지 못하여 공사(公私)의 연음(宴飮)이 끊이지 아니하여 비용을 허비하며 즐기니, 전하께서 조심하고 두려워하여 수성(修省)하시는 마음에 어긋남이 있습니다. 바라옵건대, 제향(祭享)의 공상(供上)과 중국 사신(使臣)의 연향(宴享) 이외에는 일절 모두 술을 금하소서.\" 하니, 임금이 말하였다. \"금년 봄에 담근 술이 이미 익었으니 ...\"\n\n(※ 원문 전체 및 한문 원전은 국사편찬위원회 조선왕조실록 링크에서 확인하실 수 있습니다.)",
