    "summary": "금주령(禁酒令)을 내리었으니 헌부(憲府)의 청을 따른 것이다. 참판승추부사(參判承樞府事) 윤저(尹抵)가 아뢰기를, \"매년 술을 금하는데, 재상(宰相)은 죄를 받은 사람이 없습니다. 신도 역시 술을 많이 빚었는데 어떻게 감히 땅에 버릴 수가 있습니까? 한두 사람의 친구와 더불어 문을 닫고 마시면 누가 알겠습니까? 저 술을 팔아서 생활하는 자들이 불행하게 죄를 당하니, 그 정상이 가긍(可矜)합니...",
    "officialRecord": "금주령(禁酒令)을 내리었으니 헌부(憲府)의 청을 따른 것이다. 참판승추부사(參判承樞府事) 윤저(尹抵)가 아뢰기를, \"매년 술을 금하는데, 재상(宰相)은 죄를 받은 사람이 없습니다. 신도 역시 술을 많이 빚었는데 어떻게 감히 땅에 버릴 수가 있습니까? 한두 사람의 친구와 더불어 문을 닫고 마시면 누가 알겠습니까? 저 술을 팔아서 생활하는 자들이 불행하게 죄를 당하니, 그 정상이 가긍(可矜)합니...",
    "yasaStory": "1404년(태종 4년) 2월 25일 실록에 실제로 기록된 이야기입니다.\n\n당시 조정과 백성들 사이에서 일어난 이 사건은 《태종실록 7권》에 다음과 같이 생생히 남아 있습니다.\n\n\"금주령(禁酒令)을 내리었으니 헌부(憲府)의 청을 따른 것이다. 참판승추부사(參判承樞府事) 윤저(尹抵)가 아뢰기를, \"매년 술을 금하는데, 재상(宰相)은 죄를 받은 사람이 없습니다. 신도 역시 술을 많이 빚었는데 어떻게 감히 땅에 버릴 수가 있습니까? 한두 사람의 친구와 더불어 문을 닫고 마시면 누가 알겠습니까? 저 술을 팔아서 생활하는 자들이 불행하게 죄를 당하니, 그 정상이 가긍(可矜)합니...\"\n\n(※ 원문 전체 및 한문 원전은 국사편찬위원회 조선왕조실록 링크에서 확인하실 수 있습니다.)",
