    "summary": "금주령(禁酒令)을 거듭하였다. 의정부에 명하기를, \"형조(刑曹)에서 아뢴 것을 보니, 금주령은 서인(庶人)에게만 행하고 귀인(貴人)·근신(近臣)에게는 행하지 않아서, 간혹 원망을 부르는 일이 있다 하니, 이제부터 금주령을 없애고 다만 공사(公私)의 연음(宴飮)만을 금하는 것이 어떠한가? 의논하여 들리라.\" 하니, 의정부에서 아뢰었다. \"금주령은 마땅히 예전대로 하여야 합니다.\"",
