    "summary": "금주령(禁酒令)이 있었기 때문이었다. 복시(覆試) 초시(初試)에 급제한 사람이 다시 보던 과거(科擧). 회시(會試).",
    "officialRecord": "금주령(禁酒令)이 있었기 때문이었다. 복시(覆試) 초시(初試)에 급제한 사람이 다시 보던 과거(科擧). 회시(會試).",
