    "yasaStory": "1414년(태종 14년) 6월 8일 실록에 실제로 기록된 이야기입니다.\n\n당시 조정과 백성들 사이에서 일어난 이 사건은 《태종실록 27권》에 다음과 같이 생생히 남아 있습니다.\n\n\"궁녀(宮女)가 3천 명이요, 공후(公侯)는 시첩(侍妾)이 적어도 2,30명을 내려가지 않는다고 합니다. 전하(殿下)의 존귀(尊貴)함으로써 궁첩(宮妾)이 수십 명에 지나지 않으니, 어찌 이것을 많다고 하여 내보낼수 있겠습니까? 비록 밖으로 내보낸다고 하더라도, 다시 가실(家室)을 가질 계책이 없으니, 그 원한은 더욱 깊어질 것입니다.\" 대언(代言) 등의 대답도 또한 이와 같았으나, 임금이 \"...\"\n\n(※ 원문 전체 및 한문 원전은 국사편찬위원회 조선왕조실록 링크에서 확인하실 수 있습니다.)",
