    "summary": "궁녀 두서너 사람을 내보내니, 사람들이 말하기를, ‘밖에 내보내면 도리어 한재(旱災)를 초래할 것입니다. ’고 하였으나, 내가 듣지 않고 내보내었는데, 지금 들으니, 그 궁녀 세 사람이 지금까지 시집가지 못하고 의지할 데가 없어서 생계가 심히 곤란하다고 한다. 그들을 불러 돌아와서 궁에 들어오게 하고, 조금이라도 산업(産業)이 있는 자는 불러 들어오게 할 것이 없다.\" 고 하였다.",
    "officialRecord": "궁녀 두서너 사람을 내보내니, 사람들이 말하기를, ‘밖에 내보내면 도리어 한재(旱災)를 초래할 것입니다. ’고 하였으나, 내가 듣지 않고 내보내었는데, 지금 들으니, 그 궁녀 세 사람이 지금까지 시집가지 못하고 의지할 데가 없어서 생계가 심히 곤란하다고 한다. 그들을 불러 돌아와서 궁에 들어오게 하고, 조금이라도 산업(産業)이 있는 자는 불러 들어오게 할 것이 없다.\" 고 하였다.",
