    "yasaStory": "1478년(성종 9년) 12월 11일 실록에 실제로 기록된 이야기입니다.\n\n당시 조정과 백성들 사이에서 일어난 이 사건은 《성종실록 99권》에 다음과 같이 생생히 남아 있습니다.\n\n\"耳目)을 기쁘게 하는 자는 화려한 옷으로 예쁘게 꾸민 궁녀이며, 궁문(宮門)을 아홉 겹으로 닫히고 임금에게 아뢰려면 천 길이나 멀리 떨어졌는데, 명신(名臣)을 불러 바깥 일을 묻고 조종(祖宗)의 기강(紀綱)을 묻고 조정(朝廷)의 득실(得失)을 묻는 일은 보이지 않습니다. ‘간이(簡易)의 허명(虛名)만을 닦으면 승평(昇平)의 교화(敎化)를 더하지 못한다.’ 하였는데, 이것은 참으로 천하...\"\n\n(※ 원문 전체 및 한문 원전은 국사편찬위원회 조선왕조실록 링크에서 확인하실 수 있습니다.)",
