    "yasaStory": "1398년(태조 7년) 6월 3일 실록에 실제로 기록된 이야기입니다.\n\n당시 조정과 백성들 사이에서 일어난 이 사건은 《태조실록 14권》에 다음과 같이 생생히 남아 있습니다.\n\n\"뇌물을 받았다가 일이 발각되니, 직첩(職牒)을 회수하고 국문(鞫問)하였다.\"\n\n(※ 원문 전체 및 한문 원전은 국사편찬위원회 조선왕조실록 링크에서 확인하실 수 있습니다.)",
