    "yasaStory": "1405년(태종 5년) 9월 6일 실록에 실제로 기록된 이야기입니다.\n\n당시 조정과 백성들 사이에서 일어난 이 사건은 《태종실록 10권》에 다음과 같이 생생히 남아 있습니다.\n\n\"뇌물을 받고 오결(誤決)하여 정상(情狀)이 현저한 자는 직첩(職牒)을 회수하고 장(杖) 1백 대를 때리고, 자신은 수군(水軍)에 채워서 영구히 서용(敍用)하지 않을 것.\" 수판(受判) 수교(受敎). 결사관(決事官) 송사를 결단 하는 관원. 판지(判旨) 교지(敎旨).\"\n\n(※ 원문 전체 및 한문 원전은 국사편찬위원회 조선왕조실록 링크에서 확인하실 수 있습니다.)",
