    "summary": "뇌물로 주고, 몰래 압록강(鴨綠江)을 건너기를 청하니, 김용이 데리고 강가에 이르러, 갈대를 베어 떼[桴]를 만들어서 건네주었다. 명이가 파사부(婆娑府)에 이르러, 사찰(伺察)하는 사람에게 잡혔다. 형조에서 아뢰기를, \"율에 준(准)하면, 본국을 배반하고 몰래 다른 나라로 가는 자나, 다만 공모만 한 자도 수범(首犯)·종범(從犯)을 분간하지 않고 모두 벱니다.\" 하니, 그대로 따랐다.",
