    "yasaStory": "1392년(태조 1년) 10월 12일 실록에 실제로 기록된 이야기입니다.\n\n당시 조정과 백성들 사이에서 일어난 이 사건은 《태조실록 2권》에 다음과 같이 생생히 남아 있습니다.\n\n\"먼저 용도를 절약해야 된다고 하니, 검소를 숭상하고 사치를 제거하는 일은 용도를 절약하는 큰 것이며, 부세( 賦稅)의 징수를 경감하고 폐단이 있는 법을 고치는 일은 백성들을 사랑하는 큰 것입니다. 옛날의 그 나라를 잘 다스리는 사람은 토지의 생산을 헤아려 그 공부(貢賦)를 정하고, 재물의 수입을 헤아려 그 용도를 절약하였으니, 이것이 경상(經常)의 법입니다. 무릇 나라를 다스리는 사람...\"\n\n(※ 원문 전체 및 한문 원전은 국사편찬위원회 조선왕조실록 링크에서 확인하실 수 있습니다.)",
