    "yasaStory": "1405년(태종 5년) 8월 22일 실록에 실제로 기록된 이야기입니다.\n\n당시 조정과 백성들 사이에서 일어난 이 사건은 《태종실록 10권》에 다음과 같이 생생히 남아 있습니다.\n\n\"서인(庶人)이 추천(追薦)할 때에, 재물이 있는 자는 사치(奢侈)를 극진히 하여 보기에 아름다운 것을 구(求)하고, 재물이 없는 자도 세속(世俗)을 따라서 빌리고 꾸기까 지 하니, 심히 성현(聖賢)의 교훈을 남긴 뜻이 아니고, 또 불씨(佛氏)의 맑고 깨끗한 도도 아닙니다. 이제부터는 부모에게 추천(追薦)하는 제도를, 유복지친(有服之親) 이외에도 절에 가서 불배(佛排)하는 것을 허락하지 ...\"\n\n(※ 원문 전체 및 한문 원전은 국사편찬위원회 조선왕조실록 링크에서 확인하실 수 있습니다.)",
