    "yasaStory": "1409년(태종 9년) 2월 17일 실록에 실제로 기록된 이야기입니다.\n\n당시 조정과 백성들 사이에서 일어난 이 사건은 《태종실록 17권》에 다음과 같이 생생히 남아 있습니다.\n\n\")과 정랑 성엄(成揜)이 파면되었다. 처음에 부사직(副司直) 최금강(崔金剛)이 그 종매(從妹) 수미(須彌)가 부사직 송현우(宋玄祐)와 간통하였다고 고발하였는데, 형조에서 ‘간통하는 것을 붙잡은 것도 아니고, 노비(奴婢)를 다투는 일로 인하여 분함을 품고 간통하였다고 지적한 것’이라 하여, 최금강의 직첩(職牒)을 거두고 법률에 의하여 논죄 하도록 청하니, 최금강의 아내가 신문고(申聞鼓)를...\"\n\n(※ 원문 전체 및 한문 원전은 국사편찬위원회 조선왕조실록 링크에서 확인하실 수 있습니다.)",
