    "summary": "사간원이 아뢰기를, \"우봉 현령 박수(朴琇)는 글을 몰라 일을 전적으로 하리(下吏)에게 맡기므로 하리들이 이를 기회로 삼아 농간을 부려 온 경내에 원성이 자자하니 파직하소서. 본현은 누차 무관의 손을 거치는 동안에 파괴된 것이 매우 심하여 만약 적임자가 아니면 소생시킬 수가 없으니 자상하고 근실한 사람을 각별히 가려 보내소서. 요즘 경상도 도체찰사가 올린 서장으로 인하여 암행 어사를 내보낼...",
    "officialRecord": "사간원이 아뢰기를, \"우봉 현령 박수(朴琇)는 글을 몰라 일을 전적으로 하리(下吏)에게 맡기므로 하리들이 이를 기회로 삼아 농간을 부려 온 경내에 원성이 자자하니 파직하소서. 본현은 누차 무관의 손을 거치는 동안에 파괴된 것이 매우 심하여 만약 적임자가 아니면 소생시킬 수가 없으니 자상하고 근실한 사람을 각별히 가려 보내소서. 요즘 경상도 도체찰사가 올린 서장으로 인하여 암행 어사를 내보낼...",
    "yasaStory": "1597년(선조 30년) 7월 13일 실록에 실제로 기록된 이야기입니다.\n\n당시 조정과 백성들 사이에서 일어난 이 사건은 《선조실록 90권》에 다음과 같이 생생히 남아 있습니다.\n\n\"사간원이 아뢰기를, \"우봉 현령 박수(朴琇)는 글을 몰라 일을 전적으로 하리(下吏)에게 맡기므로 하리들이 이를 기회로 삼아 농간을 부려 온 경내에 원성이 자자하니 파직하소서. 본현은 누차 무관의 손을 거치는 동안에 파괴된 것이 매우 심하여 만약 적임자가 아니면 소생시킬 수가 없으니 자상하고 근실한 사람을 각별히 가려 보내소서. 요즘 경상도 도체찰사가 올린 서장으로 인하여 암행 어사를 내보낼...\"\n\n(※ 원문 전체 및 한문 원전은 국사편찬위원회 조선왕조실록 링크에서 확인하실 수 있습니다.)",
