    "officialRecord": "장령 박건이 아뢰기를, \"신들이 강원·충청 두 도의 암행 어사가 조사한 불법 문서를 고찰하였는데, 그 가운데 미곡(米穀)과 잡물(雜物)을 나누어 먹고 사용(私用)한 곳이 있으니, 이것은 당연히 각도에 행이(行移)하여 추고로 처치하여야 됩니다. 영월군(寧越郡)에는 은(銀)을 산 무명에 관한 건기(件記)가 한 장 있는데, 은값의 무명이 20필에 이르렀으나 이 은을 어느 곳에 사용하였는지 모르겠...",
