    "yasaStory": "1410년(태종 10년) 4월 5일 실록에 실제로 기록된 이야기입니다.\n\n당시 조정과 백성들 사이에서 일어난 이 사건은 《태종실록 19권》에 다음과 같이 생생히 남아 있습니다.\n\n\"도둑을 피하고, 도로(道路)가 통하지 못하여 경원(慶源) 두 능(陵)의 삭망 전물(朔望奠物)과 병마사(兵馬使)의 늠급(廩給)을 미처 수송하지 못하고, 도적들이 잇달아 침략하기 때문에, 부가참(富家站) 이북의 사람들이 밭 1무(畝)도 경작하지 않고 모두 떠날 마음이 있습니다.\" 하였다.\"\n\n(※ 원문 전체 및 한문 원전은 국사편찬위원회 조선왕조실록 링크에서 확인하실 수 있습니다.)",
