    "summary": "시험하여, 전가식(田可植)을 제1등으로 뽑고, 전가식·조서(趙敍)·이공의(李公義)에게 내구마(內廐馬) 각각 1필씩을 하사하였다. 조서는 조영무(趙英茂)의 아들이요, 이공의는 이무(李茂)의 아들이었다. 민제(閔霽)가 문생(門生)들에게 그의 집에서 잔치를 베푸니, 임금이 중관(中官)을 보내어 술을 하사하였다.",
    "officialRecord": "시험하여, 전가식(田可植)을 제1등으로 뽑고, 전가식·조서(趙敍)·이공의(李公義)에게 내구마(內廐馬) 각각 1필씩을 하사하였다. 조서는 조영무(趙英茂)의 아들이요, 이공의는 이무(李茂)의 아들이었다. 민제(閔霽)가 문생(門生)들에게 그의 집에서 잔치를 베푸니, 임금이 중관(中官)을 보내어 술을 하사하였다.",
    "yasaStory": "1399년(정종 1년) 4월 5일 실록에 실제로 기록된 이야기입니다.\n\n당시 조정과 백성들 사이에서 일어난 이 사건은 《정종실록 1권》에 다음과 같이 생생히 남아 있습니다.\n\n\"시험하여, 전가식(田可植)을 제1등으로 뽑고, 전가식·조서(趙敍)·이공의(李公義)에게 내구마(內廐馬) 각각 1필씩을 하사하였다. 조서는 조영무(趙英茂)의 아들이요, 이공의는 이무(李茂)의 아들이었다. 민제(閔霽)가 문생(門生)들에게 그의 집에서 잔치를 베푸니, 임금이 중관(中官)을 보내어 술을 하사하였다.\"\n\n(※ 원문 전체 및 한문 원전은 국사편찬위원회 조선왕조실록 링크에서 확인하실 수 있습니다.)",
