    "yasaStory": "1407년(태종 7년) 4월 18일 실록에 실제로 기록된 이야기입니다.\n\n당시 조정과 백성들 사이에서 일어난 이 사건은 《태종실록 13권》에 다음과 같이 생생히 남아 있습니다.\n\n\"문신(文臣)들을 광연루(廣延樓) 아래에서 친히 시험하였는데, 좌정승(左政丞) 하윤(河崙)·대제학(大提學) 권근(權近)으로 독권관(讀券官) 을 삼고, 이조 참의(吏曹參議) 맹사성(孟思誠)·지신사(知申事) 황희(黃喜)로 대독관(對讀官) 을 삼았다. 중외(中外)의 시산 문신(時散文臣) 종3품(從三品) 이하 응시(應試)한 자가 1백 8인이었는데, 장막(帳幕)을 베 풀고 종이[紙]·벼루[硯]·주...\"\n\n(※ 원문 전체 및 한문 원전은 국사편찬위원회 조선왕조실록 링크에서 확인하실 수 있습니다.)",
