    "summary": "시험하여, 그 고하의 차례대로 장부에다 이 름을 쓰고, 벌(罰) 받는 것의 다소도 여기에 쓰게 할 것. 부학(部學) 서울에 설치한 5부 학당(五部學堂)을 일컫는 말임. 1. 옛날에 모든 백성 가운데 준수(俊秀)한 자가 태학(大學)에 들어가던 법에 의하여, 대소 인원(大小人員)과 서인(庶人)의 자제(子弟)로서 부학(部學)에 있는 자가 식년(式年)에 이르면, 예조에서 1원(員)과 동관원(同館員)...",
    "officialRecord": "시험하여, 그 고하의 차례대로 장부에다 이 름을 쓰고, 벌(罰) 받는 것의 다소도 여기에 쓰게 할 것. 부학(部學) 서울에 설치한 5부 학당(五部學堂)을 일컫는 말임. 1. 옛날에 모든 백성 가운데 준수(俊秀)한 자가 태학(大學)에 들어가던 법에 의하여, 대소 인원(大小人員)과 서인(庶人)의 자제(子弟)로서 부학(部學)에 있는 자가 식년(式年)에 이르면, 예조에서 1원(員)과 동관원(同館員)...",
    "yasaStory": "1413년(태종 13년) 6월 30일 실록에 실제로 기록된 이야기입니다.\n\n당시 조정과 백성들 사이에서 일어난 이 사건은 《태종실록 25권》에 다음과 같이 생생히 남아 있습니다.\n\n\"시험하여, 그 고하의 차례대로 장부에다 이 름을 쓰고, 벌(罰) 받는 것의 다소도 여기에 쓰게 할 것. 부학(部學) 서울에 설치한 5부 학당(五部學堂)을 일컫는 말임. 1. 옛날에 모든 백성 가운데 준수(俊秀)한 자가 태학(大學)에 들어가던 법에 의하여, 대소 인원(大小人員)과 서인(庶人)의 자제(子弟)로서 부학(部學)에 있는 자가 식년(式年)에 이르면, 예조에서 1원(員)과 동관원(同館員)...\"\n\n(※ 원문 전체 및 한문 원전은 국사편찬위원회 조선왕조실록 링크에서 확인하실 수 있습니다.)",
