    "summary": "과거의 지공거(知貢擧)였는데 김한로 등이 모두 그 문생(門生)이었고, 임금도 잠저(潛邸)에 있을 때 또한 그 시험에 합격하였다. 지공거(知貢擧) 과거를 보이는 시험관(試驗官)을 말함. 문생(門生) 과거에 합격한 사람들이 고시관(考試官)인 은문(恩門)에 대하여 자신을 스스로 일컫던 말. 평생 문하(門下)의 예를 취하였음.",
