    "yasaStory": "1414년(태종 14년) 4월 24일 실록에 실제로 기록된 이야기입니다.\n\n당시 조정과 백성들 사이에서 일어난 이 사건은 《태종실록 27권》에 다음과 같이 생생히 남아 있습니다.\n\n\"과거의 지공거(知貢擧)였는데 김한로 등이 모두 그 문생(門生)이었고, 임금도 잠저(潛邸)에 있을 때 또한 그 시험에 합격하였다. 지공거(知貢擧) 과거를 보이는 시험관(試驗官)을 말함. 문생(門生) 과거에 합격한 사람들이 고시관(考試官)인 은문(恩門)에 대하여 자신을 스스로 일컫던 말. 평생 문하(門下)의 예를 취하였음.\"\n\n(※ 원문 전체 및 한문 원전은 국사편찬위원회 조선왕조실록 링크에서 확인하실 수 있습니다.)",
