    "yasaStory": "1432년(세종 14년) 3월 13일 실록에 실제로 기록된 이야기입니다.\n\n당시 조정과 백성들 사이에서 일어난 이 사건은 《세종실록 55권》에 다음과 같이 생생히 남아 있습니다.\n\n\"능히 감당할 만한 자가 드물 것이니, 모름지기 강경 시험을 시행해야 한다. ’고 하였다. 그러나 이것은 그 한 쪽만 보고 하는 말이다. 성인을 제외한 그 이하의 사람은 사정(私情)을 쓰는 일을 면하지 못할 것이다. 강경 시험으로 〈시험관과 수험생이〉 면대(面對)히였을 때에 혹은 친척이라던가, 혹은 친구라던가, 혹은 권문 세가(權門勢家)의 아들에게 어찌 감히 강인(强靭)하게 질문하겠는...\"\n\n(※ 원문 전체 및 한문 원전은 국사편찬위원회 조선왕조실록 링크에서 확인하실 수 있습니다.)",
