    "summary": "시험하며, 생원(生員)도 또한 예조에서 주관하고, 성균관이 같이 시험한다.’ 하였는데, 이제 과거를 당할 때마다 시원(試員)들이 상피(相避)를 칭탁하고 사퇴하니, 법을 세운 본의에 위배됨이 있다. 이후로는 상피에 저촉되는 거자(擧子)는 응시하지 말게 하라.\" 시원(試員) 고시원. 거자(擧子) 응시자. 하였다.",
    "officialRecord": "시험하며, 생원(生員)도 또한 예조에서 주관하고, 성균관이 같이 시험한다.’ 하였는데, 이제 과거를 당할 때마다 시원(試員)들이 상피(相避)를 칭탁하고 사퇴하니, 법을 세운 본의에 위배됨이 있다. 이후로는 상피에 저촉되는 거자(擧子)는 응시하지 말게 하라.\" 시원(試員) 고시원. 거자(擧子) 응시자. 하였다.",
