    "yasaStory": "1419년(세종 1년) 1월 21일 실록에 실제로 기록된 이야기입니다.\n\n당시 조정과 백성들 사이에서 일어난 이 사건은 《세종실록 3권》에 다음과 같이 생생히 남아 있습니다.\n\n\"아뢰소서. 저도 아뢰겠습니다.\" 고 하였다. 사신은 화포(火砲)를 보여 달라 하기로, 하명하여 화붕(火棚)을 설비케 하고, 어둠녘에 사신과 더불어 관문(館門)에 나가 구경하는데 불이 터지니, 유천은 흥미있게 보다가 놀라 들어갔다. 다시 나오기를 두 번이나 했고, 황엄은 놀라지 않는 체하나, 낯빛은 약간 흔들렸다. 상왕은 사신에게 안장 갖춘 말을 선사하니, 황엄은 받고, 유천은 받지 아...\"\n\n(※ 원문 전체 및 한문 원전은 국사편찬위원회 조선왕조실록 링크에서 확인하실 수 있습니다.)",
