    "yasaStory": "1422년(세종 4년) 8월 19일 실록에 실제로 기록된 이야기입니다.\n\n당시 조정과 백성들 사이에서 일어난 이 사건은 《세종실록 17권》에 다음과 같이 생생히 남아 있습니다.\n\n\"화포(火砲)와 병기(兵器)를 설치하여, 밤낮으로 그 위에서 적의 변동하는 것을 관망하게 하소서.\" 하니, 그대로 따르고, 여러 도에 명하여 모두 연대(烟臺)를 쌓으라고 명하였다.\"\n\n(※ 원문 전체 및 한문 원전은 국사편찬위원회 조선왕조실록 링크에서 확인하실 수 있습니다.)",
