    "officialRecord": "달라고 주청하였더니 명나라의 고황제(高皇帝)가 특히 화포(火砲)와 화약을 하사 하였다. 이것은 일시동인(一視同仁)의 큰 법인 것이다. 우리 나라가 동쪽으로 왜적(倭賊)과 이웃하고 있으므로, 부득이 전함(戰艦)을 준비하였으나, 그러나 한 해를 넘기지 못하고 이미 부패(腐敗)하게 되었으니 대체로 공장(工匠)의 조선 기술(造船技術)이 완전하지 못하기 때문이다. 이제 마땅히 먼저 고황제가 화...",
    "yasaStory": "1432년(세종 14년) 5월 16일 실록에 실제로 기록된 이야기입니다.\n\n당시 조정과 백성들 사이에서 일어난 이 사건은 《세종실록 56권》에 다음과 같이 생생히 남아 있습니다.\n\n\"달라고 주청하였더니 명나라의 고황제(高皇帝)가 특히 화포(火砲)와 화약을 하사 하였다. 이것은 일시동인(一視同仁)의 큰 법인 것이다. 우리 나라가 동쪽으로 왜적(倭賊)과 이웃하고 있으므로, 부득이 전함(戰艦)을 준비하였으나, 그러나 한 해를 넘기지 못하고 이미 부패(腐敗)하게 되었으니 대체로 공장(工匠)의 조선 기술(造船技術)이 완전하지 못하기 때문이다. 이제 마땅히 먼저 고황제가 화...\"\n\n(※ 원문 전체 및 한문 원전은 국사편찬위원회 조선왕조실록 링크에서 확인하실 수 있습니다.)",
