    "officialRecord": "면에 있게 한다. 무릇 행군하고 결진하고 전투할 때에 의병(疑兵)을 세우는 일, 보충하는 일, 척후를 하는 일들은 오로지 이 유격군의 책임으로 한다. 만약 군의 수효가 더 많으면 이런 수효로 비율을 정한다. 모든 군이 머물러 숙소를 정하는 데에는 모두 다 지역을 나누어 갈피를 그어서 그 한계선을 분명히 하여 통행을 금하고, 길처를 말끔히 하여 대장의 명령이 아니면 통행할 수 없게 하고...",
    "yasaStory": "1433년(세종 15년) 7월 4일 실록에 실제로 기록된 이야기입니다.\n\n당시 조정과 백성들 사이에서 일어난 이 사건은 《세종실록 61권》에 다음과 같이 생생히 남아 있습니다.\n\n\"면에 있게 한다. 무릇 행군하고 결진하고 전투할 때에 의병(疑兵)을 세우는 일, 보충하는 일, 척후를 하는 일들은 오로지 이 유격군의 책임으로 한다. 만약 군의 수효가 더 많으면 이런 수효로 비율을 정한다. 모든 군이 머물러 숙소를 정하는 데에는 모두 다 지역을 나누어 갈피를 그어서 그 한계선을 분명히 하여 통행을 금하고, 길처를 말끔히 하여 대장의 명령이 아니면 통행할 수 없게 하고...\"\n\n(※ 원문 전체 및 한문 원전은 국사편찬위원회 조선왕조실록 링크에서 확인하실 수 있습니다.)",
