    "summary": "기우제를 지내기 위하여 내향(內香)을 받들고 유후사로 가는 도중에 도관찰사 이지(李至)를 만났다. 이지는 말에서 내려 몸을 굽혔으나, 조반은 말 탄 채로 지나니, 이지가, \"나도 친히 왕지(王旨)를 받아 부월(鈇鉞)을 갖추고 왔는데, 지금 조반이 말을 탄 채 곧장 지나가니 이것이 어찌 예의겠는가?\" 하고, 헌사에 이문(移文)하게 되었다. 헌사에서 조반을 탄핵하고 청죄했으나, 임금이 그를 용서...",
    "officialRecord": "기우제를 지내기 위하여 내향(內香)을 받들고 유후사로 가는 도중에 도관찰사 이지(李至)를 만났다. 이지는 말에서 내려 몸을 굽혔으나, 조반은 말 탄 채로 지나니, 이지가, \"나도 친히 왕지(王旨)를 받아 부월(鈇鉞)을 갖추고 왔는데, 지금 조반이 말을 탄 채 곧장 지나가니 이것이 어찌 예의겠는가?\" 하고, 헌사에 이문(移文)하게 되었다. 헌사에서 조반을 탄핵하고 청죄했으나, 임금이 그를 용서...",
    "yasaStory": "1395년(태조 4년) 8월 14일 실록에 실제로 기록된 이야기입니다.\n\n당시 조정과 백성들 사이에서 일어난 이 사건은 《태조실록 8권》에 다음과 같이 생생히 남아 있습니다.\n\n\"기우제를 지내기 위하여 내향(內香)을 받들고 유후사로 가는 도중에 도관찰사 이지(李至)를 만났다. 이지는 말에서 내려 몸을 굽혔으나, 조반은 말 탄 채로 지나니, 이지가, \"나도 친히 왕지(王旨)를 받아 부월(鈇鉞)을 갖추고 왔는데, 지금 조반이 말을 탄 채 곧장 지나가니 이것이 어찌 예의겠는가?\" 하고, 헌사에 이문(移文)하게 되었다. 헌사에서 조반을 탄핵하고 청죄했으나, 임금이 그를 용서...\"\n\n(※ 원문 전체 및 한문 원전은 국사편찬위원회 조선왕조실록 링크에서 확인하실 수 있습니다.)",
