    "officialRecord": "하겠는가?’ 하며, 이에 혹은 여악(女樂)으로, 혹은 사냥 으로, 혹은 노리갯감으로, 혹은 토목(土木)일 같은 것으로써 무릇 황음무도(荒淫無道)한 일을 말하지 않음이 없으니, 임금은 ‘이것이 나를 사랑함이 두텁다.’ 하여, 자연으로 태만해지고 거칠어지게 되는 것을 알지 못하게 되니, 한(漢)·당(唐)의 임금들이 예전 삼대(三代) 때만 못하다는 것이 이것입니다. 그렇다면 임금으로서 하루라...",
    "yasaStory": "1395년(태조 4년) 10월 7일 실록에 실제로 기록된 이야기입니다.\n\n당시 조정과 백성들 사이에서 일어난 이 사건은 《태조실록 8권》에 다음과 같이 생생히 남아 있습니다.\n\n\"하겠는가?’ 하며, 이에 혹은 여악(女樂)으로, 혹은 사냥 으로, 혹은 노리갯감으로, 혹은 토목(土木)일 같은 것으로써 무릇 황음무도(荒淫無道)한 일을 말하지 않음이 없으니, 임금은 ‘이것이 나를 사랑함이 두텁다.’ 하여, 자연으로 태만해지고 거칠어지게 되는 것을 알지 못하게 되니, 한(漢)·당(唐)의 임금들이 예전 삼대(三代) 때만 못하다는 것이 이것입니다. 그렇다면 임금으로서 하루라...\"\n\n(※ 원문 전체 및 한문 원전은 국사편찬위원회 조선왕조실록 링크에서 확인하실 수 있습니다.)",
