    "yasaStory": "1441년(세종 23년) 8월 18일 실록에 실제로 기록된 이야기입니다.\n\n당시 조정과 백성들 사이에서 일어난 이 사건은 《세종실록 93권》에 다음과 같이 생생히 남아 있습니다.\n\n\"호조에서 아뢰기를, \"각도 감사(監司)가 우량(雨量)을 전보(轉報)하도록 이미 성법(成法)이 있사오니, 토성(土性)의 조습(燥濕)이 같지 아니하고, 흙속으로 스며 든 천심(淺深)도 역시 알기 어렵사오니, 청하옵건대, 서운관(書雲觀)에 대(臺)를 짓고 쇠로 그릇을 부어 만들되, 길이는 2척이 되게 하고 직경은 8촌이 되게 하여, 대(臺) 위에 올려 놓고 비를 받아, 본관(本觀) 관원으로 하여...\"\n\n(※ 원문 전체 및 한문 원전은 국사편찬위원회 조선왕조실록 링크에서 확인하실 수 있습니다.)",
